-- GreenTech interactive module workflow. Scope: GreenTech only.
-- Builds on 0011 GreenSkills core and 0012 GreenTech competency workspaces.

create table if not exists public.greentech_module_progress(
 id uuid primary key default gen_random_uuid(), participant_id uuid not null references public.participants(id) on delete cascade,
 lesson_id uuid not null references public.greenskills_lessons(id) on delete cascade, section_no integer not null check(section_no between 1 and 7),
 completed boolean not null default true, reflection text, updated_at timestamptz not null default now(), unique(participant_id,lesson_id,section_no));
alter table public.greentech_module_progress enable row level security;
create policy "staff read GreenTech module progress by site" on public.greentech_module_progress for select to authenticated using(exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id)));
create policy "authorized staff manage GreenTech module progress" on public.greentech_module_progress for all to authenticated using(exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id))) with check(public.current_profile_role() in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') and exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id)));

create table if not exists public.greentech_module_submissions(
 id uuid primary key default gen_random_uuid(), participant_id uuid not null references public.participants(id) on delete cascade,
 lesson_id uuid not null references public.greenskills_lessons(id) on delete cascade, section_no integer not null check(section_no between 1 and 7),
 submission_type text not null check(submission_type in ('LEARNING_RESPONSE','ASSESSMENT_RESPONSE','DIY_RESPONSE')), payload jsonb not null default '{}'::jsonb,
 status text not null default 'SUBMITTED' check(status in ('DRAFT','SUBMITTED','VERIFIED','REQUIRES_REMEDIATION')), reviewed_by uuid references public.profiles(id), reviewed_at timestamptz,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(participant_id,lesson_id,section_no,submission_type));
alter table public.greentech_module_submissions enable row level security;
create policy "staff read GreenTech module submissions by site" on public.greentech_module_submissions for select to authenticated using(exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id)));
create policy "authorized staff manage GreenTech module submissions" on public.greentech_module_submissions for all to authenticated using(exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id))) with check(public.current_profile_role() in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') and exists(select 1 from public.participants p where p.id=participant_id and public.same_site(p.site_id)));
create index if not exists greentech_module_submission_idx on public.greentech_module_submissions(participant_id,lesson_id,section_no);

create or replace function public.submit_greentech_module_section(p_session_token text,p_lesson_code text,p_section_no integer,p_submission_type text,p_payload jsonb)
returns uuid language plpgsql security definer set search_path='public' as $$ declare v_participant uuid;v_lesson uuid;v_id uuid;v_type text:=upper(coalesce(p_submission_type,''));begin
 if p_session_token is null or length(p_session_token)<>64 then raise exception 'Invalid learner session';end if;
 if p_section_no not between 1 and 7 or v_type not in ('LEARNING_RESPONSE','ASSESSMENT_RESPONSE','DIY_RESPONSE') then raise exception 'Invalid module submission';end if;
 if pg_column_size(p_payload)>100000 then raise exception 'Submission too large';end if;
 select las.participant_id into v_participant from public.learner_access_sessions las join public.participants p on p.id=las.participant_id where las.token_hash=encode(digest(p_session_token,'sha256'),'hex') and las.revoked_at is null and las.expires_at>now() and p.active=true limit 1;
 if v_participant is null then raise exception 'Learner session expired';end if;select id into v_lesson from public.greenskills_lessons where lesson_code=p_lesson_code and active=true limit 1;if v_lesson is null then raise exception 'Unknown module';end if;
 insert into public.greentech_module_submissions(participant_id,lesson_id,section_no,submission_type,payload,status) values(v_participant,v_lesson,p_section_no,v_type,p_payload,'SUBMITTED') on conflict(participant_id,lesson_id,section_no,submission_type) do update set payload=excluded.payload,status='SUBMITTED',updated_at=now() returning id into v_id;
 insert into public.greentech_module_progress(participant_id,lesson_id,section_no,completed) values(v_participant,v_lesson,p_section_no,true) on conflict(participant_id,lesson_id,section_no) do update set completed=true,updated_at=now();return v_id;end $$;
revoke all on function public.submit_greentech_module_section(text,text,integer,text,jsonb) from public;grant execute on function public.submit_greentech_module_section(text,text,integer,text,jsonb) to anon,authenticated;

create or replace function public.get_greentech_learner_progress(p_session_token text,p_lesson_code text)
returns table(section_no integer,completed boolean,reflection text) language plpgsql security definer set search_path='public' as $$ declare v_participant uuid;v_lesson uuid;begin select las.participant_id into v_participant from public.learner_access_sessions las where las.token_hash=encode(digest(p_session_token,'sha256'),'hex') and las.revoked_at is null and las.expires_at>now() limit 1;if v_participant is null then return;end if;select id into v_lesson from public.greenskills_lessons where lesson_code=p_lesson_code and active=true limit 1;return query select g.section_no,g.completed,g.reflection from public.greentech_module_progress g where g.participant_id=v_participant and g.lesson_id=v_lesson order by g.section_no;end $$;
revoke all on function public.get_greentech_learner_progress(text,text) from public;grant execute on function public.get_greentech_learner_progress(text,text) to anon,authenticated;

create or replace function public.get_greentech_staff_participants() returns table(id uuid,preferred_name text) language sql security definer set search_path='public' as $$ select p.id,p.preferred_name from public.participants p where p.active=true and public.same_site(p.site_id) and public.current_profile_role() in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') order by p.preferred_name $$;
revoke all on function public.get_greentech_staff_participants() from public,anon;grant execute on function public.get_greentech_staff_participants() to authenticated;

create or replace function public.record_greentech_staff_assessment(p_participant_id uuid,p_lesson_code text,p_mcq_score numeric,p_theory_score numeric,p_knowledge integer,p_practical integer,p_data_digital integer,p_safety integer,p_enterprise integer,p_leadership integer,p_evidence_note text default null,p_status text default 'VERIFIED') returns uuid language plpgsql security definer set search_path='public' as $$ declare v_lesson uuid;v_assessment uuid;v_site uuid;v_passport_code text;begin
 if auth.uid() is null or public.current_profile_role() not in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') then raise exception 'Not authorized';end if;select site_id into v_site from public.participants where id=p_participant_id and active=true;if v_site is null or not public.same_site(v_site) then raise exception 'Participant not in authorized site';end if;select id into v_lesson from public.greenskills_lessons where lesson_code=p_lesson_code and active=true limit 1;if greatest(p_knowledge,p_practical,p_data_digital,p_safety,p_enterprise,p_leadership)>5 or least(p_knowledge,p_practical,p_data_digital,p_safety,p_enterprise,p_leadership)<0 then raise exception 'Ratings must be 0-5';end if;
 insert into public.greenskills_lesson_assessments(participant_id,lesson_id,knowledge_score,practical_rating,data_digital_rating,safety_rating,enterprise_employability_rating,leadership_rating,theory_score,mcq_score,evidence_note,status,assessed_by,assessed_at) values(p_participant_id,v_lesson,p_knowledge*20,p_practical,p_data_digital,p_safety,p_enterprise,p_leadership,p_theory_score,p_mcq_score,p_evidence_note,p_status,auth.uid(),now()) returning id into v_assessment;
 v_passport_code:='GS-'||upper(substr(replace(p_participant_id::text,'-',''),1,10));insert into public.skills_passports(participant_id,passport_code,knowledge_score,practical_score,data_digital_score,safety_score,enterprise_employability_score,leadership_score,status,updated_at) values(p_participant_id,v_passport_code,p_knowledge*20,p_practical*20,p_data_digital*20,p_safety*20,p_enterprise*20,p_leadership*20,'ACTIVE',now()) on conflict(participant_id) do update set knowledge_score=excluded.knowledge_score,practical_score=excluded.practical_score,data_digital_score=excluded.data_digital_score,safety_score=excluded.safety_score,enterprise_employability_score=excluded.enterprise_employability_score,leadership_score=excluded.leadership_score,updated_at=now();return v_assessment;end $$;
revoke all on function public.record_greentech_staff_assessment(uuid,text,numeric,numeric,integer,integer,integer,integer,integer,integer,text,text) from public,anon;grant execute on function public.record_greentech_staff_assessment(uuid,text,numeric,numeric,integer,integer,integer,integer,integer,integer,text,text) to authenticated;

create or replace function public.record_greentech_practical_assessment(p_participant_id uuid,p_lesson_code text,p_safety_gate_passed boolean,p_critical_safety_failure boolean,p_preparation text,p_safety text,p_tools text,p_measurement text,p_execution text,p_testing text,p_troubleshooting text,p_documentation text,p_communication text,p_competency_rating integer,p_decision text,p_assessor_notes text default null) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_lesson uuid;v_site uuid;v_id uuid;v_attempt integer;begin if auth.uid() is null or public.current_profile_role() not in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') then raise exception 'Not authorized';end if;select site_id into v_site from public.participants where id=p_participant_id and active=true;if v_site is null or not public.same_site(v_site) then raise exception 'Participant not in authorized site';end if;select id into v_lesson from public.greenskills_lessons where lesson_code=p_lesson_code and active=true limit 1;select coalesce(max(attempt_no),0)+1 into v_attempt from public.greentech_practical_assessments where participant_id=p_participant_id and lesson_id=v_lesson;insert into public.greentech_practical_assessments(participant_id,lesson_id,attempt_no,safety_gate_passed,critical_safety_failure,preparation_status,safety_status,tools_status,measurement_status,execution_status,testing_status,troubleshooting_status,documentation_status,communication_status,competency_rating,decision,assessor_notes,assessed_by,assessed_at) values(p_participant_id,v_lesson,v_attempt,p_safety_gate_passed,p_critical_safety_failure,p_preparation,p_safety,p_tools,p_measurement,p_execution,p_testing,p_troubleshooting,p_documentation,p_communication,p_competency_rating,p_decision,p_assessor_notes,auth.uid(),now()) returning id into v_id;return v_id;end $$;
revoke all on function public.record_greentech_practical_assessment(uuid,text,boolean,boolean,text,text,text,text,text,text,text,text,text,integer,text,text) from public,anon;grant execute on function public.record_greentech_practical_assessment(uuid,text,boolean,boolean,text,text,text,text,text,text,text,text,text,integer,text,text) to authenticated;

create or replace function public.verify_greentech_fieldwork(p_evidence_id uuid,p_verified boolean) returns boolean language plpgsql security definer set search_path='public' as $$ declare v_participant uuid;v_site uuid;begin if auth.uid() is null or public.current_profile_role() not in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') then raise exception 'Not authorized';end if;select f.participant_id,p.site_id into v_participant,v_site from public.fieldwork_evidence f join public.participants p on p.id=f.participant_id where f.id=p_evidence_id;if v_participant is null or not public.same_site(v_site) then raise exception 'Evidence not in authorized site';end if;update public.fieldwork_evidence set verification_status=case when p_verified then 'VERIFIED' else 'REJECTED' end,verified_by=auth.uid(),verified_at=now() where id=p_evidence_id;return found;end $$;
revoke all on function public.verify_greentech_fieldwork(uuid,boolean) from public,anon;grant execute on function public.verify_greentech_fieldwork(uuid,boolean) to authenticated;

create or replace function public.get_greentech_staff_workspace(p_participant_id uuid,p_lesson_code text) returns jsonb language plpgsql security definer set search_path='public' as $$ declare v_lesson uuid;v_site uuid;v_result jsonb;begin if auth.uid() is null or public.current_profile_role() not in ('SUPER_ADMIN','PROGRAM_ADMIN','SITE_COORDINATOR','EDUCATOR','M_AND_E_OFFICER') then raise exception 'Not authorized';end if;select site_id into v_site from public.participants where id=p_participant_id and active=true;if v_site is null or not public.same_site(v_site) then raise exception 'Participant not in authorized site';end if;select id into v_lesson from public.greenskills_lessons where lesson_code=p_lesson_code and active=true limit 1;select jsonb_build_object('progress',(select coalesce(jsonb_agg(jsonb_build_object('section_no',section_no,'completed',completed,'reflection',reflection) order by section_no),'[]'::jsonb) from public.greentech_module_progress where participant_id=p_participant_id and lesson_id=v_lesson),'submissions',(select coalesce(jsonb_agg(to_jsonb(x) order by section_no,updated_at desc),'[]'::jsonb) from (select id,section_no,submission_type,payload,status,reviewed_at,updated_at from public.greentech_module_submissions where participant_id=p_participant_id and lesson_id=v_lesson)x),'ai_logs',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from(select id,ai_layer,task,status,created_at from public.greentech_ai_work_logs where participant_id=p_participant_id and lesson_id=v_lesson)x),'enterprise',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from(select id,customer_problem,service_scope,status,competency_rating,created_at from public.greentech_enterprise_tasks where participant_id=p_participant_id and lesson_id=v_lesson)x),'practical',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from(select id,attempt_no,safety_gate_passed,competency_rating,decision,assessor_notes,created_at from public.greentech_practical_assessments where participant_id=p_participant_id and lesson_id=v_lesson)x),'assessments',(select coalesce(jsonb_agg(to_jsonb(x) order by assessed_at desc nulls last),'[]'::jsonb) from(select id,knowledge_score,practical_rating,data_digital_rating,safety_rating,enterprise_employability_rating,leadership_rating,theory_score,mcq_score,evidence_note,status,assessed_at from public.greenskills_lesson_assessments where participant_id=p_participant_id and lesson_id=v_lesson)x),'fieldwork',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from(select id,evidence_type,title,description,file_url,verification_status,created_at from public.fieldwork_evidence where participant_id=p_participant_id and lesson_id=v_lesson)x),'passport',(select to_jsonb(x) from(select passport_code,knowledge_score,practical_score,data_digital_score,safety_score,enterprise_employability_score,leadership_score,verified_field_hours,status,updated_at from public.skills_passports where participant_id=p_participant_id)x)) into v_result;return v_result;end $$;
revoke all on function public.get_greentech_staff_workspace(uuid,text) from public,anon;grant execute on function public.get_greentech_staff_workspace(uuid,text) to authenticated;
